require __DIR__.'/config.php';$p=db();$token=$_GET['token']??'';$s=$p->prepare("SELECT * FROM online_orders WHERE token=?");$s->execute([$token]);$o=$s->fetch();if(!$o){http_response_code(404);exit('Pedido não encontrado.');}$s=$p->prepare("SELECT * FROM online_order_items WHERE online_order_id=?");$s->execute([$o['id']]);$items=$s->fetchAll();$cfg=$p->query("SELECT * FROM public_catalog_settings WHERE id=1")->fetch()?:[];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="catalog.css"><title><?=e($o['public_number'])?></title></head><body><main style="max-width:720px;margin:30px auto;padding:16px"><div class="product" style="padding:20px"><h1><?=e($o['public_number'])?></h1><p>Obrigado, <b><?=e($o['customer_name'])?></b>.</p><p>Status: <b><?=e($o['status'])?></b> • Pagamento: <b><?=e($o['payment_status'])?></b></p><h3>Itens</h3><?php foreach($items as $i):?><p><?=$i['qty']?>x <?=e($i['product_name'])?> — <?=money($i['qty']*$i['unit_price'])?></p><?php endforeach;?><hr><p>Total: <b><?=money($o['total'])?></b></p><?php if(!empty($cfg['pix_key'])):?><h3>Pagamento via Pix</h3><p>Chave: <b><?=e($cfg['pix_key'])?></b></p><p>Favorecido: <?=e($cfg['pix_receiver'])?></p><?php endif;?><p><?=e($cfg['order_confirmation_text']??'Recebemos seu pedido.')?></p></div></main></body></html>